import assert from 'node:assert/strict';
import { handleMultiAgentChatRequest } from './handlers/multiAgentChat.ts';
import { globalRegistry } from './providers/registry.ts';

const calls: string[] = [];
const provider = { id: 'repro', name: 'repro', type: 'openai' as const, supportsImages: () => false, async *executeChat(request: {message: string}) {
  calls.push(request.message);
  if (request.message === '@parent start') yield { type: 'tool_use' as const, toolName: 'delegate_task', toolInput: { agent_id: 'child', instructions: 'work' } };
  else if (request.message === 'work') yield { type: 'text' as const, content: 'child output' };
  else yield { type: 'text' as const, content: 'finished' };
  yield { type: 'done' as const };
}};
globalRegistry.registerProvider(provider);
for (const id of ['parent', 'child']) globalRegistry.registerAgent({id, name: id, description: '', provider: 'repro'});
const context = { req: { json: async () => ({message: '@parent start', requestId: 'repro'}) }, var: {config: {debugMode: false}} };
const response = await handleMultiAgentChatRequest(context as never, new Map());
const chunks = (await response.text()).trim().split('\n').map(line => JSON.parse(line));
assert(calls.includes('work'), 'child must receive delegated instructions');
const feedback = calls.find(message => { try { return JSON.parse(message).type === 'tool_result'; } catch { return false; } });
assert(feedback, 'parent must receive tool result');
assert.equal(JSON.parse(feedback).content, 'child output');
assert(chunks.some(chunk => chunk.data?.type === 'tool_use'), 'tool use must be streamed');
console.log('Delegation reproduction passed');
